<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:Arial,sans-serif;font-size:8px}h1{text-align:center;font-size:14px}table{border-collapse:collapse;width:100%;font-size:7px}th,td{border:1px solid #333;padding:3px;text-align:center}th{background:#d9e2f3}td:nth-child(2){text-align:left}.export-header{position:relative;text-align:center;margin-bottom:8px}.export-logo{position:absolute;top:0;width:42px;height:42px}.export-logo.left{left:20px}.export-logo.right{right:20px}.signatures{width:100%;margin-top:16px;text-align:center}.signatures td{width:50%;border:0;text-align:left;padding-left:50px}.signature-stack{width:190px}.signature-gap{height:24px}.signature-line{border-bottom:1px solid #333;width:190px}.signature-name{text-align:center;font-weight:bold;margin-top:4px}.signature-role{text-align:center;margin-top:2px}.title{text-align:center}</style></head><body><div class="export-header"><img class="export-logo left" src="{{ \App\Services\SchoolLogoService::path() }}"><img class="export-logo right" src="{{ public_path('images/id/deped.png') }}"><h1>SCHOOL-BASED FEEDING PROGRAM - RECORD OF DAILY FEEDING</h1><p class="title">For the month of {{ date('F', mktime(0,0,0,$month->month,1)) }}, SY {{ $month->schoolYear->year }}</p></div><table><thead><tr><th>No.</th><th>Name of Pupil</th><th>Grade Level</th><th>Section</th>@foreach(range(1, date('t', mktime(0,0,0,$month->month,1,$calendarYear))) as $day)<th>{{ $day }}</th>@endforeach</tr></thead><tbody>@foreach($students as $student)<tr><td>{{ $student['number'] }}</td><td>{{ $student['name'] }}</td><td>{{ $student['grade_level'] === 0 ? 'Kinder' : ($student['grade_level'] === 7 ? 'SPED' : 'Grade '.$student['grade_level']) }}</td><td>{{ $student['section'] }}</td>@foreach($student['days'] as $status)<td>{{ in_array(strtolower((string)$status),['present','p','served']) ? 'P' : (in_array(strtolower((string)$status),['absent','a']) ? 'A' : '') }}</td>@endforeach</tr>@endforeach</tbody></table><table class="